import math
def control(obs):
    h=math.radians(obs['hitch_deg'])
    cam=obs.get('views',{}).get('camera')
    if not cam: return (0,0,-23)
    axis=math.pi-h
    pts=[]
    for b,d in cam.get('walls',[]):
        a=math.radians(b)-axis
        u=d*math.cos(a); z=-d*math.sin(a)
        if u>0.3: pts.append((u,z))
    def side(sign,U):
        p=sorted((u,z) for u,z in pts if z*sign>0.5)
        if not p:return None
        for i in range(len(p)-1):
            a,b=p[i],p[i+1]
            if a[0]<=U<=b[0]:
                f=(U-a[0])/max(.001,b[0]-a[0]);return a[1]+f*(b[1]-a[1])
        return min(p,key=lambda p:abs(p[0]-U))[1]
    U=4.0
    l=side(1,U); r=side(-1,U)
    if l is None or r is None:return (obs['hitch_deg']*2,0,-23)
    z=(l+r)/2
    hd=math.atan(2*2.6*z/(U*U+z*z))
    hd=max(-.52,min(.52,hd))
    eq=math.atan(2.75*math.sin(h)/(2.6+1.05*math.cos(h)))
    steer=math.degrees(eq+2.2*(h-hd))
    return (max(-34,min(34,steer)),-.65,-23)

